                        Ok(s) => subs.push(s),
                        Err(err) => {
                            sub_err = Some(format!("sse subscribe '{name}' error: {err}"));
                            break;
                        }
                    }
                }
                if let Some(err) = sub_err {
                    log::error!("{err}");
                    status.set(concise_error(&err));
                    gloo_timers::future::TimeoutFuture::new(2_000).await;
                    continue;
                }

