                // now close this source immediately even if OPEN never arrives.
                set_stream_source(
                    &planner_stream_sources,
                    &active_session_id,
                    generation,
                    false,
                    Some(es.clone()),
                );
                let opened = await_event_source_open(&es).await;
                if sse_generation.get_untracked() != generation
                    || !stream_owner_matches(
                        &planner_stream_sources.borrow(),
                        &active_session_id,
                        generation,
                    )
                {
                    break;
                }
                if !opened {
                    set_stream_source(
                        &planner_stream_sources,
                        &active_session_id,
                        generation,
                        false,
                        None,
                    );
                    status.set("agent stream did not open".into());
                    continue;
                }
                if !mark_stream_source_open(
                    &planner_stream_sources,
                    &active_session_id,
                    generation,
                    false,
                ) {
                    break;
                }
                agent_stream_ready.set(stream_marker_for_state(
                    es.state(),
                    &active_session_id,
                    generation,
                ));
                spawn_local(monitor_stream_open(
                    planner_stream_sources.clone(),
                    agent_stream_ready,
                    active_session_id.clone(),
                    generation,
                    false,
                ));
                let mut stream = futures_util::stream::select_all(subs);
                while let Some(msg) = stream.next().await {
                    if sse_generation.get_untracked() != generation {
                        break;
                    }

