                        break;
                    }

                    apply_event(
                        &evt,
                        turns,
                        session_id,
                        streaming,
                        status,
                        status_detail,
                        last_turn_tokens,
                        session_tokens,
                        model,
                        active_turn_id,
                        browser_active,
                        browser_last_action,
                        canvas_patches,
                        pinned_widgets,
                        awaiting_session_adoption,
                        session_title,
                        cwd,
                    );
                }

                clear_stream_marker(agent_stream_ready, &active_session_id, generation);
                set_stream_source(
                    &planner_stream_sources,
                    &active_session_id,
                    generation,
                    false,
                    None,
                );
