}

fn close_planner_stream_sources(sources: &Rc<RefCell<PlannerStreamSources>>) {
    let (agent, permission) = {
        let mut sources = sources.borrow_mut();
        let agent = sources.agent.take();
        let permission = sources.permission.take();
        sources.session_id.clear();
        sources.generation = 0;
        sources.lifecycle.reset();
        (agent, permission)
    };
    // gloo-net 0.6 clones share one web_sys::EventSource. `close` wakes the
    // subscriber stream; doing it after the borrow is released avoids a
    // re-entrant RefCell borrow through the dispatched close notification.
    if let Some(agent) = agent {
        agent.close();
    }
    if let Some(permission) = permission {
        permission.close();
    }
}

fn set_stream_source(
    sources: &Rc<RefCell<PlannerStreamSources>>,
    session_id: &str,
    generation: u64,
    permission: bool,
    source: Option<EventSource>,
) {
    let previous = {
        let mut sources = sources.borrow_mut();
        if sources.session_id != session_id || sources.generation != generation {
            return;
        }
        let state = source
            .as_ref()
            .map(EventSource::state)
            .unwrap_or(EventSourceState::Closed);
        let (kind, previous) = if permission {
            (
                PlannerStreamKind::Permission,
                std::mem::replace(&mut sources.permission, source),
            )
        } else {
            (
                PlannerStreamKind::Agent,
                std::mem::replace(&mut sources.agent, source),
            )
        };
        sources.lifecycle.transition(kind, state);
        previous
    };
    if let Some(previous) = previous {
        previous.close();
    }
}

fn stream_owner_matches(sources: &PlannerStreamSources, session_id: &str, generation: u64) -> bool {
    sources.session_id == session_id && sources.generation == generation
}

/// Mark one already-installed CONNECTING source OPEN without replacing its
/// stored clone. Replacement would drop/close the exact source we just awaited.
fn mark_stream_source_open(
    sources: &Rc<RefCell<PlannerStreamSources>>,
    session_id: &str,
    generation: u64,
    permission: bool,
) -> bool {
    let mut sources = sources.borrow_mut();
    if !stream_owner_matches(&sources, session_id, generation) {
        return false;
    }
    let installed = if permission {
        sources.permission.is_some()
    } else {
        sources.agent.is_some()
    };
    if !installed {
        return false;
    }
    sources.lifecycle.transition(
        if permission {
            PlannerStreamKind::Permission
        } else {
            PlannerStreamKind::Agent
        },
        EventSourceState::Open,
    );
    true
}

async fn monitor_stream_open(
    sources: send_wrapper::SendWrapper<Rc<RefCell<PlannerStreamSources>>>,
    marker: RwSignal<Option<(String, u64)>>,
    session_id: String,
    generation: u64,
    permission: bool,
) {
    loop {
        gloo_timers::future::TimeoutFuture::new(25).await;
        let state = {
            let sources = sources.borrow();
            if sources.session_id != session_id || sources.generation != generation {
                return;
